def step_4(input_list):
    """
    Step 4: Filter by signature.
    - Input: list (expected: list of 18 booleans OR, alternatively, a list of processed entry dicts)
    - Output: list of booleans of the same length indicating whether each entry matched one of:
        "BB:MSSQL Account Modification"
        "BB:TDV Postgres Account Modification"
      If the input is booleans (from step_3), this function will attempt to locate a companion
      list of processed entries in module globals (common names checked) to evaluate signatures.
      If no companion processed-entry list is found, the function returns a list of False values
      (conservative: cannot confirm signature matches).
    - Behavior:
      * Processes the entire input list and returns a list (one boolean per input element).
      * Handles malformed inputs gracefully and always returns a list of booleans (or empty list).
    """
    # Allowed signatures (exact match)
    allowed_signatures = {
        "BB:MSSQL Account Modification",
        "BB:TDV Postgres Account Modification"
    }

    # Input validation
    if input_list is None:
        return []
    if not isinstance(input_list, list):
        return []

    # Helper to normalize a signature value to string and check membership
    def signature_matches(sig_value):
        try:
            if sig_value is None:
                return False
            sig_str = str(sig_value).strip()
            return sig_str in allowed_signatures
        except Exception:
            return False

    # If the input appears to be a list of dicts (processed entries), extract signature directly
    if all(isinstance(item, dict) for item in input_list):
        results = []
        for idx, processed_entry in enumerate(input_list):
            try:
                # Expect signature on original event: processed_entry['original']['signature']
                signature_value = None
                original = processed_entry.get("original") if isinstance(processed_entry.get("original"), dict) else None
                if original is not None:
                    signature_value = original.get("signature")
                # Fallback: maybe signature was promoted to top-level in the processed entry
                if signature_value is None:
                    signature_value = processed_entry.get("signature")

                results.append(bool(signature_matches(signature_value)))
            except Exception:
                # On unexpected error for an item, return False for that position
                results.append(False)
        return results

    # If the input appears to be a list of booleans (expected step_3 output),
    # attempt to locate companion processed entries in module globals so we can check signatures.
    if all(isinstance(item, bool) for item in input_list):
        # Candidate global variable names that might hold processed entries from earlier steps
        candidate_globals = [
            'STEP_2_OUTPUT', 'step_2_output', 'STEP_2_ENTRIES', 'step_2_entries',
            'STEP_1_OUTPUT', 'step_1_output', 'STEP2_OUTPUT', 'step2_output'
        ]

        companion = None
        for name in candidate_globals:
            if name in globals():
                candidate = globals()[name]
                if isinstance(candidate, list) and len(candidate) == len(input_list) and all(isinstance(x, dict) for x in candidate):
                    companion = candidate
                    break

        if companion is None:
            # Could not find companion processed entries to evaluate signatures.
            # Conservative behavior: unable to verify signatures -> return all False
            return [False] * len(input_list)

        # We have a companion list aligned with the boolean list; combine detector boolean with signature match
        final_results = []
        for detector_bool, processed_entry in zip(input_list, companion):
            try:
                # Extract signature from companion processed entry
                original = processed_entry.get("original") if isinstance(processed_entry.get("original"), dict) else None
                signature_value = None
                if original is not None:
                    signature_value = original.get("signature")
                if signature_value is None:
                    signature_value = processed_entry.get("signature")

                sig_ok = signature_matches(signature_value)
                # Final decision: only True if detector matched previously AND signature matches allowed set
                final_results.append(bool(detector_bool and sig_ok))
            except Exception:
                final_results.append(False)
        return final_results

    # Mixed-type list or unknown content: attempt best-effort processing per element.
    # For each element: if dict -> check signature; if bool -> conservative False (no companion context)
    results = []
    for item in input_list:
        try:
            if isinstance(item, dict):
                original = item.get("original") if isinstance(item.get("original"), dict) else None
                signature_value = original.get("signature") if original is not None else item.get("signature")
                results.append(bool(signature_matches(signature_value)))
            elif isinstance(item, bool):
                # No signature context for this boolean element -> conservative False
                results.append(False)
            else:
                results.append(False)
        except Exception:
            results.append(False)

    return results

